package com.muthumol.player.dummy;
import android.content.*;import android.os.*;import android.graphics.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Two bounded background workers. Persistent small image cache; no video requests. */
final class ArtworkStore {
 interface Listener{void artworkChanged();}interface Transport{byte[] get(String url,int limit)throws Exception;}
 static final class Entry {final String path,source,page,kind;Entry(String p,String s,String u,String k){path=p;source=s;page=u;kind=k;}}
 private static ArtworkStore instance;static synchronized ArtworkStore get(Context c){if(instance==null)instance=new ArtworkStore(c.getApplicationContext(),Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"Online artwork");t.setDaemon(true);return t;}),ArtworkStore::fetch);return instance;}
 final Context context;final File dir;final SharedPreferences prefs;final java.util.concurrent.Executor workers;final Transport net;final Handler ui=new Handler(Looper.getMainLooper());final Set<Listener> listeners=Collections.newSetFromMap(new WeakHashMap<>());final Set<String> pending=new HashSet<>();final Map<String,JSONObject> shows=new HashMap<>();volatile boolean active;
 ArtworkStore(Context c,java.util.concurrent.Executor w,Transport n){context=c;dir=new File(c.getFilesDir(),"artwork-v1");prefs=c.getSharedPreferences("artwork-v1",0);workers=w;net=n;}
 void add(Listener l){listeners.add(l);}void remove(Listener l){listeners.remove(l);}void active(boolean a){active=a;}
 static String hash(String key){try{return AppUpdater.hex(java.security.MessageDigest.getInstance("SHA-256").digest(key.getBytes("UTF-8")));}catch(Exception e){throw new IllegalStateException(e);}}
 static String cacheId(MediaTitle title){return hash("cover53:"+(title.episodic()?"series:":"film:")+MediaTitle.normalize(title.name)+":"+title.year);}
 Entry cached(Movie m){if(m==null)return null;String id=cacheId(MediaTitle.parse(MovieDetails.override(context,m)));try{JSONObject j=new JSONObject(prefs.getString(id,"{}"));File f=new File(dir,id+".jpg");if(!f.isFile()||f.length()==0||!(j.optString("kind").equals("movie poster")||j.optString("kind").equals("series cover")))return null;return new Entry(f.getAbsolutePath(),j.optString("source"),j.optString("page"),j.optString("kind"));}catch(Exception e){return null;}}
 Entry cachedBackdrop(Movie m){if(m==null)return null;String id=cacheId(MediaTitle.parse(MovieDetails.override(context,m)))+"-backdrop";try{JSONObject j=new JSONObject(prefs.getString(id,"{}"));File f=new File(dir,id+".jpg");if(!f.isFile()||f.length()==0||!j.optString("kind").equals("series backdrop"))return null;return new Entry(f.getAbsolutePath(),j.optString("source"),j.optString("page"),j.optString("kind"));}catch(Exception e){return null;}}
 void request(Movie m){if(!active||m==null)return;MediaTitle title=MediaTitle.parse(MovieDetails.override(context,m));if(title.name.length()<2)return;if(title.episodic()&&cachedBackdrop(m)==null)requestBackdrop(title);if(cached(m)!=null)return;String id=cacheId(title);synchronized(pending){if(pending.contains(id)||prefs.getLong(id+":retry",0)>System.currentTimeMillis())return;pending.add(id);}workers.execute(()->{boolean tried=false;try{if(!active)return;tried=true;JSONObject match=title.episodic()?seriesCover(title):film(title);if(match==null){prefs.edit().putLong(id+":retry",System.currentTimeMillis()+6*3600000L).apply();return;}if(!active)return;byte[] bytes=net.get(match.getString("image"),2*1024*1024);save(id,bytes,match);BetaLog.event("artwork_result","matched=true kind="+match.optString("kind"));}catch(Exception|OutOfMemoryError e){if(tried)prefs.edit().putLong(id+":retry",System.currentTimeMillis()+5*60000L).apply();BetaLog.event("artwork_result","matched=false type="+e.getClass().getSimpleName());}finally{synchronized(pending){pending.remove(id);}ui.post(()->{for(Listener l:new ArrayList<>(listeners))l.artworkChanged();});}});}
 void requestBackdrop(MediaTitle title){String id=cacheId(title)+"-backdrop";synchronized(pending){if(pending.contains(id)||prefs.getLong(id+":retry",0)>System.currentTimeMillis())return;pending.add(id);}workers.execute(()->{boolean tried=false;try{if(!active)return;tried=true;JSONObject match=seriesBackdrop(title);if(match==null){prefs.edit().putLong(id+":retry",System.currentTimeMillis()+6*3600000L).apply();return;}if(!active)return;save(id,net.get(match.getString("image"),4*1024*1024),match);BetaLog.event("artwork_result","matched=true kind=series backdrop");}catch(Exception|OutOfMemoryError e){if(tried)prefs.edit().putLong(id+":retry",System.currentTimeMillis()+5*60000L).apply();BetaLog.event("artwork_result","matched=false kind=series backdrop type="+e.getClass().getSimpleName());}finally{synchronized(pending){pending.remove(id);}ui.post(()->{for(Listener l:new ArrayList<>(listeners))l.artworkChanged();});}});}
 void prefetch(List<Movie> movies,Movie selected){request(selected);for(Movie m:movies)request(m);}
 JSONObject film(MediaTitle t)throws Exception{
  String q=t.name+(t.year>0?" "+t.year:"")+" film";
  JSONObject response=new JSONObject(new String(net.get("https://en.wikipedia.org/w/api.php?action=query&format=json&formatversion=2&generator=search&gsrsearch="+enc(q)+"&gsrlimit=5&prop=pageimages%7Cextracts&piprop=thumbnail%7Cname&pithumbsize=960&pilicense=any&exintro=1&explaintext=1&exchars=450",512*1024),"UTF-8"));
  return pickFilm(t,response);
 }
 static JSONObject pickFilm(MediaTitle t,JSONObject response)throws Exception{JSONObject query=response.optJSONObject("query");JSONArray pages=query==null?null:query.optJSONArray("pages");if(pages==null)return null;JSONObject best=null;double score=.79;
  for(int i=0;i<pages.length();i++){JSONObject p=pages.getJSONObject(i),thumb=p.optJSONObject("thumbnail");String name=p.optString("title"),intro=p.optString("extract");String imageName=p.optString("pageimage",thumb==null?"":thumb.optString("source")).toLowerCase(Locale.ROOT);boolean cover=thumb!=null&&(thumb.optInt("height")>thumb.optInt("width")*1.15||imageName.matches(".*(poster|cover|theatrical|promotional).*"));if(!cover)continue;String category=(name+" "+intro.substring(0,Math.min(130,intro.length()))).toLowerCase(Locale.ROOT);if(category.contains("soundtrack")||category.contains("filmography")||category.contains("franchise")||category.contains("disambiguation"))continue;if(thumb==null||!(name.toLowerCase(Locale.ROOT).contains("film")||intro.toLowerCase(Locale.ROOT).contains("film")))continue;String clean=name.replaceAll("\\s*\\([^)]*\\)","");double s=MediaTitle.similarity(t.name,clean);if(s<.8)continue;if(t.year>0){java.util.regex.Matcher year=MediaTitle.YEAR.matcher(intro.isEmpty()?name:intro);if(year.find()&&Integer.parseInt(year.group(1))!=t.year)continue;if(name.contains(""+t.year)||intro.contains(""+t.year))s+=.1;}if(s>score){score=s;best=new JSONObject().put("image",thumb.optString("source")).put("source","Wikipedia").put("kind","movie poster").put("page","https://en.wikipedia.org/wiki/"+enc(name.replace(' ','_')));}}
  return best;
 }
 JSONObject findShow(MediaTitle t)throws Exception{String key=MediaTitle.normalize(t.name)+":"+t.year;synchronized(shows){JSONObject show=shows.get(key);if(show!=null)return show;JSONArray results=new JSONArray(new String(net.get("https://api.tvmaze.com/search/shows?q="+enc(t.name),512*1024),"UTF-8"));show=pickShow(t,results);if(show!=null)shows.put(key,show);return show;}}
 JSONObject seriesCover(MediaTitle t)throws Exception{JSONObject show=findShow(t);if(show==null)return null;JSONObject image=show.optJSONObject("image");if(image==null)return null;
  return new JSONObject().put("image",image.optString("original",image.optString("medium"))).put("source","TVmaze").put("kind","series cover").put("page",show.optString("url"));
 }
 JSONObject seriesBackdrop(MediaTitle t)throws Exception{JSONObject show=findShow(t);if(show==null||show.optLong("id")<=0)return null;JSONArray images=new JSONArray(new String(net.get("https://api.tvmaze.com/shows/"+show.optLong("id")+"/images",1024*1024),"UTF-8"));JSONObject best=null;long bestArea=-1;int bestType=0;for(int i=0;i<images.length();i++){JSONObject image=images.optJSONObject(i);if(image==null)continue;String type=image.optString("type");int rank=type.equals("background")?2:type.equals("banner")?1:0;if(rank==0)continue;JSONObject resolutions=image.optJSONObject("resolutions"),original=resolutions==null?null:resolutions.optJSONObject("original");String url=original==null?"":original.optString("url");if(url.isEmpty())continue;long area=(long)(original.optInt("width"))*(long)(original.optInt("height"));if(rank>bestType||rank==bestType&&area>bestArea){bestType=rank;bestArea=area;best=new JSONObject().put("image",url).put("source","TVmaze").put("kind","series backdrop").put("page",show.optString("url"));}}return best;}
 static JSONObject pickShow(MediaTitle t,JSONArray results)throws Exception{JSONObject best=null;double score=.79;for(int i=0;i<results.length();i++){JSONObject s=results.getJSONObject(i).getJSONObject("show");double n=MediaTitle.similarity(t.name,s.optString("name"));if(n<.8)continue;String start=s.optString("premiered");if(t.year>0&&start.startsWith(""+t.year))n+=.15;if(n>score){best=s;score=n;}}return best;}
 void save(String id,byte[] raw,JSONObject metadata)throws Exception{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,o);if(o.outWidth<=0||o.outHeight<=0||(long)o.outWidth*o.outHeight>32000000)throw new IOException("Invalid image");o.inSampleSize=1;while(o.outWidth/o.inSampleSize>960||o.outHeight/o.inSampleSize>960)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=Bitmap.Config.RGB_565;Bitmap b=BitmapFactory.decodeByteArray(raw,0,raw.length,o);if(b==null)throw new IOException("Image decode failed");dir.mkdirs();File temp=new File(dir,id+".part"),target=new File(dir,id+".jpg");try{try(OutputStream out=new FileOutputStream(temp)){if(!b.compress(Bitmap.CompressFormat.JPEG,86,out))throw new IOException("Image write failed");}if(!temp.renameTo(target))throw new IOException("Image cache unavailable");prefs.edit().putString(id,metadata.toString()).remove(id+":retry").apply();trim();}finally{b.recycle();temp.delete();}}
 void trim(){File[] files=dir.listFiles((d,n)->n.endsWith(".jpg"));if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());long total=0;for(int i=0;i<files.length;i++){total+=files[i].length();if(i>=60||total>20*1024*1024)files[i].delete();}}
 void invalidate(Movie m){String id=cacheId(MediaTitle.parse(MovieDetails.override(context,m))),backdrop=id+"-backdrop";prefs.edit().remove(id).remove(id+":retry").remove(backdrop).remove(backdrop+":retry").apply();new File(dir,id+".jpg").delete();new File(dir,backdrop+".jpg").delete();}
 static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 static boolean allowed(URL u){String h=u.getHost().toLowerCase(Locale.ROOT);return "https".equals(u.getProtocol())&&(u.getPort()==-1||u.getPort()==443)&&u.getUserInfo()==null&&(h.equals("en.wikipedia.org")||h.equals("upload.wikimedia.org")||h.equals("api.tvmaze.com")||h.equals("static.tvmaze.com")||h.equals("www.wikidata.org"));}
 static byte[] fetch(String raw,int limit)throws Exception{URL u=new URL(raw);for(int redirects=0;redirects<4;redirects++){if(!allowed(u))throw new IOException("Artwork host refused");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(4500);c.setReadTimeout(6000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","TGstream/5.3 (https://github.com/rinsanak/TelePlay_gpt_patched)");try{int status=c.getResponseCode();if(status>=300&&status<400){u=new URL(u,c.getHeaderField("Location"));continue;}if(status==404)throw new FileNotFoundException("No artwork");if(status!=200)throw new IOException("Artwork unavailable");if(c.getContentLength()>limit)throw new IOException("Artwork too large");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>limit)throw new IOException("Artwork too large");out.write(buffer,0,n);}return out.toByteArray();}}finally{c.disconnect();}}throw new IOException("Artwork redirects");}
}
